SELECT province,
       SUM(cnt) AS cnt
FROM t_link_locale_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND del_flag = 0
  AND date BETWEEN #{startDate} AND #{endDate}
GROUP BY full_short_url, gid, province;

SELECT province,
       SUM(cnt) AS cnt
FROM t_link_locale_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, province;
